starter:
def median_manual(values):
    # Write your code here
    pass

solution:
def median_manual(values):
    ordered = list(values)
    for i in range(1, len(ordered)):
        current = ordered[i]
        j = i - 1
        while j >= 0 and ordered[j] > current:
            ordered[j + 1] = ordered[j]
            j -= 1
        ordered[j + 1] = current
    middle = len(ordered) // 2
    if len(ordered) % 2:
        return ordered[middle]
    return (ordered[middle - 1] + ordered[middle]) / 2

starter:
def summary_five(values):
    # Write your code here
    pass

solution:
def summary_five(values):
    ordered = list(values)
    total = 0
    for value in values:
        total += value
    for i in range(1, 5):
        j = i
        while j > 0 and ordered[j] < ordered[j - 1]:
            ordered[j], ordered[j - 1] = ordered[j - 1], ordered[j]
            j -= 1
    return {"mean": total / 5, "median": ordered[2],
            "range": ordered[4] - ordered[0]}

tests:
data=[9,1,8,2,5]
assert summary_five(data)=={"mean":5.0,"median":5,"range":8}
assert data==[9,1,8,2,5]
assert summary_five([3,3,3,3,3])=={"mean":3.0,"median":3,"range":0}
assert summary_five([-5,-4,-3,-2,-1])=={"mean":-3.0,"median":-3,"range":4}
assert not (set(summary_five.__code__.co_names) & {"sum", "min", "max", "sorted", "sort", "statistics", "numpy", "pandas", "np", "pd"}), "Use the requested manual calculations"

